                    r = String.valueOf(Interleave.can(s(p[1]), s(p[2]), s(p[3])));
                } else if (p[0].equals("RANDOM")) {
                    Random rnd = new Random(47);
                    String sai = null;
                    for (int t = 0; t < 3000 && sai == null; t++) {
